    async def update(
        self,
        id: str,
        *,
        revision_number: str,
        transaction_date: _dt.date | NotGiven = NOT_GIVEN,
        ref_number: str | NotGiven | None = NOT_GIVEN,
        from_inventory_site_id: str | NotGiven = NOT_GIVEN,
        to_inventory_site_id: str | NotGiven = NOT_GIVEN,
        memo: str | NotGiven | None = NOT_GIVEN,
        lines: Sequence[InventoryTransferLineUpdateInput] | NotGiven = NOT_GIVEN,
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> InventoryTransfer:
        """Update an inventory transfer.

        Changes the fields you send on an existing inventory transfer and leaves omitted fields unchanged. Requires the current `revisionNumber`. A stale `revisionNumber` returns `409 QBD_REVISION_NUMBER_STALE`: retrieve the inventory transfer, reapply your change and send the new revision. Sending a line array replaces all existing lines of that kind. See [Updates and line items](https://www.desktopaccountingapi.com/docs/quickbooks/updates-and-line-items/).

        Operation ``qbd.inventoryTransfers.update``: ``POST /v1/quickbooks-desktop/inventory-transfers/{id}``.

        Args:
            id: QuickBooks ID of the inventory transfer.
            revision_number: Current revision of this inventory transfer. Send it unchanged when updating; a stale value is rejected. QuickBooks changes it at most once per second, so a second edit within the same second keeps the same value. This API spaces its own consecutive writes to one object by over a second; edits made elsewhere in the same second are not detected.
            transaction_date: Date of this inventory transfer (YYYY-MM-DD).
            ref_number: Reference number of this inventory transfer, such as an invoice or check number. Case-sensitive. Pass ``None`` to clear it.
            from_inventory_site_id: ID of the from inventory site for this inventory transfer.
            to_inventory_site_id: ID of the to inventory site for this inventory transfer.
            memo: Internal memo for this inventory transfer; shown in reports, not on printed forms. Pass ``None`` to clear it.
            lines: Line items of this inventory transfer. When present, replaces this array: keep an existing entry by sending its id (an id alone leaves it unchanged), add one with id "-1"; existing entries you leave out are deleted. Omit the array to keep the lines unchanged. An update cannot remove every line.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The InventoryTransfer object.
        """
        return await self._client._request(
            _QBD_INVENTORY_TRANSFERS_UPDATE,
            "POST",
            "/v1/quickbooks-desktop/inventory-transfers/" + _pp("id", id),
            cast_to=InventoryTransfer.from_wire,
            body={
                "revisionNumber": revision_number,
                "transactionDate": transaction_date,
                "refNumber": ref_number,
                "fromInventorySiteId": from_inventory_site_id,
                "toInventorySiteId": to_inventory_site_id,
                "memo": memo,
                "lines": lines,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )
